le-field="line_height"></label><label><span>Letter spacing</span><input type="number" data-certloom-designer-style-field="letter_spacing_pt"></label><label><span>Overflow</span><select data-certloom-designer-style-field="overflow"><?php foreach(['shrink','wrap','clip'] as $v){ ?><option value="<?php echo $v; ?>"><?php echo $v; ?></option><?php } ?></select></label></div></div><div class="certloom-template-designer-style-group" hidden data-certloom-designer-style="shape"><div class="certloom-template-designer-style-grid"><input type="text" data-certloom-designer-style-field="fill"><input type="text" data-certloom-designer-style-field="stroke"><input type="number" data-certloom-designer-style-field="stroke_width_mm"></div></div><div class="certloom-template-designer-style-group" hidden data-certloom-designer-style="line"><div class="certloom-template-designer-style-grid"><input type="text" data-certloom-designer-style-field="stroke"><input type="number" data-certloom-designer-style-field="stroke_width_mm"></div></div></div></div><div class="certloom-template-designer-layers"><div class="certloom-template-designer-layers-head"><h4>Layers</h4><span>Front → back</span></div><div data-certloom-designer-layers></div></div></aside></div>
